def is_costas(arr):
    n = len(arr)
    for d in range(1, n):
        diffs = set()
        for i in range(n - d):
            diff = arr[i+d] - arr[i]
            if diff in diffs:
                return False
            diffs.add(diff)
    return True

def golomb(q):
    # q is prime
    # find primitive root
    def is_primitive(g, q):
        s = set()
        v = 1
        for _ in range(q-1):
            v = (v * g) % q
            s.add(v)
        return len(s) == q - 1

    prims = [g for g in range(2, q) if is_primitive(g, q)]

    for alpha in prims:
        for beta in prims:
            # alpha^i + beta^j = 1 mod q
            # j = log_beta(1 - alpha^i)

            # precompute log_beta
            log_b = {}
            v = 1
            for j in range(1, q):
                v = (v * beta) % q
                log_b[v] = j

            arr = []
            v_a = 1
            valid = True
            for i in range(1, q-1):
                v_a = (v_a * alpha) % q
                rem = (1 - v_a) % q
                if rem == 0:
                    valid = False
                    break
                arr.append(log_b[rem] - 1) # 0-indexed
            if valid and is_costas(arr):
                return arr
    return None

