def max_clique(adj):
    max_c = []
    def bk(R, P, X):
        nonlocal max_c
        if not P and not X:
            if len(R) > len(max_c):
                max_c = list(R)
            return
        if len(R) + len(P) <= len(max_c):
            return
        pivot = max(P.union(X), key=lambda u: len(P.intersection(adj[u])))
        for v in list(P - adj[pivot]):
            bk(R.union({v}), P.intersection(adj[v]), X.intersection(adj[v]))
            P.remove(v)
            X.add(v)
    bk(set(), set(range(60)), set())
    return max_c

