def gf8_mult(a, b):
    p = 0
    for i in range(3):
        if (b & (1 << i)):
            p ^= (a << i)
    # reduce modulo x^3 + x + 1 (which is 1011 in binary, i.e., 11)
    if p & 16:
        p ^= (11 << 1)
    if p & 8:
        p ^= 11
    return p

