def solve():
    n = 20
    E = 21

    # Variables: e[i][j] is true if edge (i, j) exists
    e = [[Bool(f"e_{i}_{j}") for j in range(n)] for i in range(n)]

    s = Solver()

    # Symmetry and irreflexivity
    for i in range(n):
        s.add(Not(e[i][i]))
        for j in range(i+1, n):
            s.add(e[i][j] == e[j][i])

    # At least 21 edges
    edge_vars = [e[i][j] for i in range(n) for j in range(i+1, n)]
    s.add(PbGe([(v, 1) for v in edge_vars], E))

    # Girth >= 7 means no cycles of length 3, 4, 5, 6
    # No 3-cycles
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                s.add(Not(And(e[i][j], e[j][k], e[k][i])))

    # No 4-cycles
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                for l in range(k+1, n):
                    # 3 possible 4-cycles on 4 vertices
                    s.add(Not(And(e[i][j], e[j][k], e[k][l], e[l][i])))
                    s.add(Not(And(e[i][j], e[j][l], e[l][k], e[k][i])))
                    s.add(Not(And(e[i][k], e[k][j], e[j][l], e[l][i])))

    # No 5-cycles
    import itertools
    for c in itertools.combinations(range(n), 5):
        for p in itertools.permutations(c):
            # To avoid duplicates, only consider permutations where p[0] is min, and p[1] < p[4]
            if p[0] == min(p) and p[1] < p[4]:
                s.add(Not(And(e[p[0]][p[1]], e[p[1]][p[2]], e[p[2]][p[3]], e[p[3]][p[4]], e[p[4]][p[0]])))

    # No 6-cycles
    for c in itertools.combinations(range(n), 6):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[5]:
                s.add(Not(And(e[p[0]][p[1]], e[p[1]][p[2]], e[p[2]][p[3]], e[p[3]][p[4]], e[p[4]][p[5]], e[p[5]][p[0]])))

    # 3-colorable
    c = [Int(f"c_{i}") for i in range(n)]
    for i in range(n):
        s.add(c[i] >= 0, c[i] <= 2)
    for i in range(n):
        for j in range(i+1, n):
            s.add(Implies(e[i][j], c[i] != c[j]))

    print("Solving...")
    if s.check() == sat:
        m = s.model()
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                if is_true(m[e[i][j]]):
                    edges.append((i, j))
        print("SAT")
        print(edges)
    else:
        print("UNSAT")

