import z3

def solve():
    # 20 vertices
    N = 20

    # edges
    E = [[z3.Bool(f"e_{i}_{j}") for j in range(N)] for i in range(N)]

    s = z3.Solver()

    # undirected, no self loops
    for i in range(N):
        s.add(z3.Not(E[i][i]))
        for j in range(i + 1, N):
            s.add(E[i][j] == E[j][i])

    # degree at least 5
    for i in range(N):
        s.add(z3.Sum([z3.If(E[i][j], 1, 0) for j in range(N)]) >= 5)

    # chromatic number at most 3
    # color of each vertex
    C = [z3.Int(f"c_{i}") for i in range(N)]
    for i in range(N):
        s.add(C[i] >= 0, C[i] <= 2)

    # adjacent vertices have different colors
    for i in range(N):
        for j in range(i + 1, N):
            s.add(z3.Implies(E[i][j], C[i] != C[j]))

    # max clique size at most 3 is automatically satisfied if chromatic number <= 3

    if s.check() == z3.sat:
        m = s.model()
        edges = []
        for i in range(N):
            for j in range(i + 1, N):
                if z3.is_true(m[E[i][j]]):
                    edges.extend([i, j])
        print(edges)
    else:
        print("UNSAT")

solve()

from z3 import *

def solve():
    V = 14
    E = 18

    # Adjacency matrix
    adj = [[Bool(f"e_{i}_{j}") for j in range(V)] for i in range(V)]

    s = Solver()

    # Symmetry of adjacency matrix and no self-loops
    for i in range(V):
        s.add(Not(adj[i][i]))
        for j in range(i + 1, V):
            s.add(adj[i][j] == adj[j][i])

    # At least 18 edges
    edges_sum = Sum([If(adj[i][j], 1, 0) for i in range(V) for j in range(i + 1, V)])
    s.add(edges_sum >= E)

    # Girth >= 7 means no cycles of length 3, 4, 5, 6
    # Cycle of length 3
    for i in range(V):
        for j in range(i + 1, V):
            for k in range(j + 1, V):
                s.add(Not(And(adj[i][j], adj[j][k], adj[k][i])))

    # Cycle of length 4
    for i in range(V):
        for j in range(i + 1, V):
            for k in range(j + 1, V):
                for l in range(k + 1, V):
                    # permutations of 4 vertices
                    # (i,j,k,l), (i,j,l,k), (i,k,j,l)
                    s.add(Not(And(adj[i][j], adj[j][k], adj[k][l], adj[l][i])))
                    s.add(Not(And(adj[i][j], adj[j][l], adj[l][k], adj[k][i])))
                    s.add(Not(And(adj[i][k], adj[k][j], adj[j][l], adj[l][i])))

    # Cycle of length 5
    import itertools
    for c in itertools.combinations(range(V), 5):
        for p in itertools.permutations(c):
            # to avoid duplicates, fix the first element to be the minimum, and the second < last
            if p[0] == min(p) and p[1] < p[4]:
                s.add(Not(And(adj[p[0]][p[1]], adj[p[1]][p[2]], adj[p[2]][p[3]], adj[p[3]][p[4]], adj[p[4]][p[0]])))

    # Cycle of length 6
    for c in itertools.combinations(range(V), 6):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[5]:
                s.add(Not(And(adj[p[0]][p[1]], adj[p[1]][p[2]], adj[p[2]][p[3]], adj[p[3]][p[4]], adj[p[4]][p[5]], adj[p[5]][p[0]])))

    # 3-colorable
    colors = [Int(f"c_{i}") for i in range(V)]
    for i in range(V):
        s.add(colors[i] >= 0, colors[i] <= 2)
    for i in range(V):
        for j in range(i + 1, V):
            s.add(Implies(adj[i][j], colors[i] != colors[j]))

    if s.check() == sat:
        m = s.model()
        edges = []
        for i in range(V):
            for j in range(i + 1, V):
                if is_true(m[adj[i][j]]):
                    edges.append((i, j))
        print("SAT")
        print(edges)
    else:
        print("UNSAT")

solve()

