C = {}
for i in range(N):
    for c in range(4):
        C[(i, c)] = var_counter
        var_counter += 1

for i in range(N):
    # At least one color
    solver.add_clause([C[(i, c)] for c in range(4)])
    # At most one color
    for c1 in range(4):
