                    edge(cycle[1], cycle[2]),
                    edge(cycle[2], cycle[3]),
                    edge(cycle[3], cycle[4]),
                    edge(cycle[4], cycle[0])
                )))

    # Maximize edges
    total_edges = Sum([If(E[i][j], 1, 0) for i in range(V) for j in range(i+1, V)])
    opt.maximize(total_edges)

    # Symmetry breaking: degree of vertex 0 >= degree of vertex 1 >= ...
