                solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[4]), -var(p[4], p[0])])

    # Instead of adding all 6-cycles, we can use CEGAR (Counter-Example Guided Abstraction Refinement)
    print("Starting CEGAR loop...")
    iteration = 0
    while True:
