    W = 7
    G = 10
    S = 3
    P = G * S

    if len(res) != W * P:
        return False, "Length mismatch"

    # Check groups
    for w in range(W):
        groups = [[] for _ in range(G)]
        for p in range(P):
            g = res[w * P + p]
            if g < 0 or g >= G:
                return False, f"Invalid group {g}"
            groups[g].append(p)
        for g in range(G):
            if len(groups[g]) != S:
                return False, f"Group {g} in week {w} has {len(groups[g])} players"

    # Check pairs
    pairs = set()
    for w in range(W):
        groups = [[] for _ in range(G)]
        for p in range(P):
            groups[res[w * P + p]].append(p)

        for g in range(G):
            for i in range(S):
