import z3

def solve_sgp(w, g, s):
    n = g * s
    solver = z3.Solver()

    # X[week][golfer] = group
    X = [[z3.Int(f"x_{i}_{j}") for j in range(n)] for i in range(w)]

    for i in range(w):
        for j in range(n):
            solver.add(X[i][j] >= 0, X[i][j] < g)

    # Each group has exactly s golfers
    for i in range(w):
        for k in range(g):
            solver.add(z3.Sum([z3.If(X[i][j] == k, 1, 0) for j in range(n)]) == s)

    # No pair of golfers in the same group more than once
    for j1 in range(n):
        for j2 in range(j1 + 1, n):
            solver.add(z3.Sum([z3.If(X[i][j1] == X[i][j2], 1, 0) for i in range(w)]) <= 1)

    # Symmetry breaking
    # Week 0: golfers 0..n-1 are in groups 0,0,0, 1,1,1, ...
    for j in range(n):
        solver.add(X[0][j] == j // s)

    # Golfer 0 is always in group 0
    for i in range(w):
        solver.add(X[i][0] == 0)

    # Week 1: golfer 1 in group 0, golfer 2 in group 1, etc.
    # Actually, let's just let the solver do it.

    solver.set("timeout", 50000)
    if solver.check() == z3.sat:
        m = solver.model()
        res = []
        for i in range(w):
            for j in range(n):
                res.append(m.evaluate(X[i][j]).as_long())
        print("SAT")
        print(res)
    else:
        print("UNSAT or TIMEOUT")

