for j1, j2 in itertools.combinations(range(n), 2):
    # They are in the same group in week i if for some k, var(i, j1, k) and var(i, j2, k) are both true
    # Let's introduce a variable for "j1 and j2 are in the same group in week i"
    # Actually, we can just say: for any two weeks i1, i2, they cannot be in the same group in both weeks.
