def bfs_shortest_cycle(adj):
    min_cycle = float('inf')
    for i in range(24):
        dist = {i: 0}
        parent = {i: -1}
        q = [i]
        while q:
            u = q.pop(0)
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    min_cycle = min(min_cycle, dist[u] + dist[v] + 1)
    return min_cycle

