            s.add(A[i][j] == A[j][i])

    # Degree 3
    for i in range(n):
        s.add(PbEq([(A[i][j], 1) for j in range(n)], 3))

    # Girth >= 7 means no cycles of length 3, 4, 5, 6
    # Instead of all cycles, we can say: for any pair of vertices (i, j),
    # there is at most one path of length <= 3 between them.
    # Actually, it's easier to define distance variables.
    # But distance variables are expensive.

    # Let's just add clauses for cycles of length 3, 4, 5, 6.
    # To reduce the number of clauses, we can just use a lazy approach:
    # Solve, find a short cycle, add a clause to forbid it, repeat.

    import networkx as nx

    while True:
        if s.check() == sat:
            m = s.model()
            adj = {i: [] for i in range(n)}
            for i in range(n):
                for j in range(i + 1, n):
                    if is_true(m[A[i][j]]):
                        adj[i].append(j)
                        adj[j].append(i)

            # Check girth
            girth = float('inf')
            short_cycle = None

            for start in range(n):
                dist = {start: 0}
                parent = {start: None}
                queue = [start]
                for v in queue:
                    for w in adj[v]:
                        if w not in dist:
                            dist[w] = dist[v] + 1
                            parent[w] = v
                            queue.append(w)
                        elif parent[v] != w:
                            cycle_len = dist[v] + dist[w] + 1
                            if cycle_len < girth:
                                girth = cycle_len
                                # Reconstruct cycle
                                path1 = []
                                curr = v
                                while curr is not None:
                                    path1.append(curr)
                                    curr = parent[curr]
                                path1.reverse()

                                path2 = []
                                curr = w
                                while curr is not None:
                                    path2.append(curr)
                                    curr = parent[curr]

                                # Find lowest common ancestor
                                lca = None
                                for p1, p2 in zip(path1, path2):
                                    if p1 == p2:
                                        lca = p1
                                    else:
                                        break

                                idx1 = path1.index(lca)
                                idx2 = path2.index(lca)

                                cycle = path1[idx1:] + path2[idx2:][::-1]
                                short_cycle = cycle

            if girth >= 7:
                edges = []
                for i in range(n):
                    for j in range(i + 1, n):
                        if is_true(m[A[i][j]]):
                            edges.append((i, j))
                print(edges)
                return
            else:
                # Forbid this cycle
                clause = []
                for i in range(len(short_cycle)):
                    u = short_cycle[i]
                    v = short_cycle[(i + 1) % len(short_cycle)]
                    clause.append(Not(A[u][v]))
                s.add(Or(clause))
        else:
            print("UNSAT")
            return

solve()

